#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    long long s;
    if (scanf("%d %lld", &n, &s) != 2) return 0;

    // prefix sums estão no intervalo [0, 10^6]
    vector<long long> cnt(1000001, 0);
    cnt[0] = 1; // prefixo vazio

    long long p = 0;   // soma acumulada
    long long ans = 0; // resposta (pode ser grande: O(N^2) intervalos no pior caso)

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        p += x;

        long long alvo = p - s;
        if (alvo >= 0 && alvo <= 1000000) ans += cnt[alvo];

        if (p <= 1000000) cnt[p]++;
    }

    printf("%lld\n", ans);
    return 0;
}
